function gameAssetContext12(){const pick=gameSelection6,a=worldAsset12(pick.kind,pick.id),snap=worldAssetSnapshot12(pick.kind,pick.id),station=worldStationLabels12(snap).find(s=>s.id===gameStation6),inside=gameLayer6!=='city',box=el('gameContext6');box.hidden=false;const titles={bakery:'Vlastní pekárna',hq:'Kanceláře',estate:'Kávová plantáž',roaster:'Vlastní pražírna',warehouse:'Distribuční sklad'};let summary=[];if(pick.kind==='bakery')summary=[['Vyrobeno / poslední týden',a.last?.produced??'—'],['Stav zařízení',round(a.condition)+' %'],['Pekaři',a.staff],['Kapacita / den',bakeryCapacity5(a)]];else if(pick.kind==='hq'){summary=[['Pracovní místa',a.seats],['Celá centrála',usedSeats()+' / '+officeSeats()],['Provoz / týden',money(a.upkeep)]];if(DEPARTMENTS[gameStation6])summary=[['Lidé v oddělení',state.departments[gameStation6]],['Mzdy / týden',money(state.departments[gameStation6]*DEPARTMENTS[gameStation6].salary)],['Volná místa v centrále',Math.max(0,officeSeats()-usedSeats())]];}else if(pick.kind==='estate')summary=[['Původ',a.country],['Zdraví porostu',round(a.health)+' %'],['Cyklus',a.cycle+' / '+a.period+' týdnů'],['Závlaha',a.irrigation?'Instalovaná':'Bez závlahy']];else if(pick.kind==='roaster')summary=[['Kapacita / týden',roasterCapacity(a)+' kg'],['Stav',round(a.condition)+' %'],['Tým',a.staff]];else summary=[['Kapacita',number(a.capacity)+' kg'],['Oblast',a.zone]];box.innerHTML=gamePanel6(station?.name||a.name,titles[pick.kind],`<p class="game-sub6">${esc(a.name)}${pick.kind==='estate'?' · '+esc(a.country):''}</p>${innerWidth<=760?'<details class="world-asset-metrics12"><summary>Provozní údaje</summary>'+rows(summary)+'</details>':rows(summary)}${pick.kind==='hq'&&DEPARTMENTS[gameStation6]?'<p class="game-sub6">'+esc(DEPARTMENTS[gameStation6].description)+'</p>':''}<div class="game-panel-actions6"><button class="${inside?'':'game-primary6'}" id="worldEnterAsset12">${inside?'Zpět do města':'Vstoupit do provozu'}</button><button class="${inside?'game-primary6':''}" id="gameManageObject6">${station?'Spravovat '+esc(station.name):'Řídit provoz'}</button>${pick.kind==='hq'&&DEPARTMENTS[gameStation6]?'<button id="worldHireDepartment12" '+(state.cash<8000||usedSeats()>=officeSeats()||state.departments[gameStation6]>=30?'disabled':'')+'>Přijmout člověka · 8 000 Kč</button>':''}${pick.kind==='estate'&&!a.irrigation?'<button id="worldIrrigation12">Pořídit závlahu · 90 000 Kč</button>':''}${pick.kind==='bakery'?'<button id="worldBakeryService12" '+(a.condition>=100?'disabled':'')+'>Servis zařízení · '+money(a.cost*.04)+'</button>':''}${pick.kind==='roaster'?'<button id="worldRoasterService12" '+(a.condition>=100?'disabled':'')+'>Servis · 18 000 Kč</button>':''}${pick.kind==='bakery'&&a.cafe12?'<button id="worldLinkedCafe12">Zpět do propojené kavárny</button>':''}</div>`);el('worldEnterAsset12').onclick=()=>{gameLayer6=inside?'city':pick.kind;gameStation6=null;render();el('gameContext6').scrollTop=0;};el('gameManageObject6').onclick=()=>worldGoManage12(pick.kind,pick.id,gameStation6);el('gameContextClose6').onclick=()=>gameReturn6();if(el('worldHireDepartment12'))el('worldHireDepartment12').onclick=()=>{const key=gameStation6,q=worldDepartmentQuote12(key);confirmAction('Posílit '+DEPARTMENTS[key].name+'?',money(q.cost)+' za nábor, poté '+money(q.wage)+' mzda za týden. Jeden člověk využije jedno kancelářské místo.',()=>worldHireDepartment12(key,q),'Přijmout a zaplatit');};if(el('worldIrrigation12'))el('worldIrrigation12').onclick=()=>{const cash=state.cash;confirmAction('Pořídit závlahu?',money(90000)+' za skutečné závlahové zařízení. Snižuje dopad sucha v dalších týdnech.',()=>{if(state.cash!==cash||a.irrigation)throw Error('Nabídka se změnila.');irrigation(a.id);},'Zaplatit a instalovat');};if(el('worldBakeryService12'))el('worldBakeryService12').onclick=()=>confirmAction('Servis pekárny?',money(a.cost*.04)+' za obnovení stavu na 100 %.',()=>serviceBakery5(a.id));if(el('worldRoasterService12'))el('worldRoasterService12').onclick=()=>confirmAction('Servis pražírny?',money(18000)+' za obnovení stavu na 100 %.',()=>maintainRoaster(a.id));if(el('worldLinkedCafe12'))el('worldLinkedCafe12').onclick=()=>{gameSelection6={kind:'address',id:a.cafe12};gameLayer6='cafe';gameStation6=null;render();};}
function gameAttachBakeryDialog12(location){const candidates=state.bakery5.bakeries.filter(b=>b.city===loc(location).city&&!b.cafe12);show(`<h2>Vlastní pekárna · ${esc(loc(location).name)}</h2><p class="sub">Přístavba propojí konkrétní pekárnu s kavárnou a objeví se ve městě i v interiéru. Tým, výroba a odběry zůstávají skutečné a placené.</p>${candidates.length?`<label class="field">Pekárna ve stejném městě<select id="worldLinkBakery12">${candidates.map(b=>option(b.id,b.name)).join('')}</select></label><p>Přístavba · 68 000 Kč</p><button class="primary" id="worldLinkPreview12">Prověřit přístavbu</button>`:'<p>Ve městě zatím nemáš volnou vlastní pekárnu.</p>'}<button class="soft" id="worldBuyBakery12">Pořídit pekárnu ve správě výroby</button>`);el('worldBuyBakery12').onclick=()=>{uxPanels10.bakery='production';goto('bakery');};if(el('worldLinkPreview12'))el('worldLinkPreview12').onclick=()=>{try{const id=el('worldLinkBakery12').value,q=worldBakeryLinkQuote12(location,id);confirmAction('Připojit pekárnu?',money(q.cost)+' za přístavbu. Nezapíná automaticky odběr ani nepřidává další tržby.',()=>worldLinkBakery12(location,id,q),'Zaplatit a připojit');}catch(e){toast(e.message);}};}
function worldChrome12(){document.body.classList.add('world-design12');if(el('gameKpis6').parentElement!==document.querySelector('.game-top6'))document.querySelector('.game-place6').after(el('gameKpis6'));let toggle=el('worldSpaceMode12');if(!toggle){toggle=document.createElement('div');toggle.id='worldSpaceMode12';toggle.innerHTML='<button id="worldOperate12">▷ Provoz</button><button id="worldFurnish12">▱ Zařídit</button>';el('gameCanvas6').after(toggle);}toggle.hidden=gameLayer6!=='cafe';el('worldOperate12').setAttribute('aria-pressed',String(!gameEditing6));el('worldFurnish12').setAttribute('aria-pressed',String(gameEditing6));el('worldOperate12').onclick=()=>{gameEditing6=false;gameDraft6=null;render();};el('worldFurnish12').onclick=()=>el('gameEditCafe6')?.click();}

function worldIllustration12(kind){const aliases={cafes:'address',coffee:'roaster',food:'bakery',team:'hq',money:'hq',overview:'hq',trade:'warehouse',expansion:'city'},k=aliases[kind]||kind;const cube=(x,y,w,h,d,fill)=>`<path d="M${x} ${y}l${w} ${-w/2} ${d} ${d/2} ${-w} ${w/2}Z" fill="${fill}"/><path d="M${x} ${y}v${h}l${d} ${d/2}v${-h}Z" fill="#b7c1c4"/><path d="M${x+d} ${y+d/2}l${w} ${-w/2}v${h}l${-w} ${w/2}Z" fill="#8e9fa8"/>`;let content='';if(k==='estate'){for(let r=0;r<4;r++)for(let c=0;c<6;c++)content+=`<ellipse cx="${63+c*16+r*14}" cy="${42+r*11-c*4}" rx="7" ry="5" fill="#98ae88"/><circle cx="${62+c*16+r*14}" cy="${40+r*11-c*4}" r="3" fill="#6f906e"/>`;content+=cube(168,33,24,22,20,'#c49c80');}else if(k==='city'){content+='<path d="M122 17l-25 80h17l25-80Z" fill="#99b4c2"/>';for(let i=0;i<5;i++)content+=cube(42+i*34,47+i%2*10,17,16+(i%2)*8,14,['#c5bba6','#b2bbb1','#c6ab92'][i%3]);content+='<path d="M88 61l49-11 4 5-49 11Z" fill="#e4e5df"/>';}else if(k==='vehicle'){content+=cube(92,49,45,17,20,'#e0ead7');content+='<circle cx="101" cy="79" r="5" fill="#5b6a73"/><circle cx="139" cy="60" r="5" fill="#5b6a73"/>';}else{content+='<path d="M57 67V29l60-30v38Z" fill="#e8e9e3"/><path d="M117 37V-1l77 38v38Z" fill="#d3dcde"/>';if(k==='hq'){content+=cube(75,52,25,15,17,'#c3b394')+cube(120,40,25,15,17,'#c3b394')+cube(146,65,32,12,17,'#b7aa91');content+='<path d="M88 45v-13l16-8v13Z" fill="#778eab"/>';}else if(k==='bakery'||k==='roaster'){content+=cube(73,47,23,30,19,'#7e8d99')+cube(110,39,21,17,17,'#b8c1bf')+cube(128,66,41,12,18,'#c9b69b');content+='<path d="M80 54l14-7v8l-14 7Z" fill="#a9b6bc"/>';}else if(k==='warehouse'){for(let i=0;i<5;i++)content+=cube(74+i*19,58-i%2*16,16,18,12,'#c7b494');}else{content+=cube(115,31,40,24,24,'#687a95');for(let i=0;i<4;i++)content+=cube(71+i%2*40,65+Math.floor(i/2)*14-i%2*14,19,8,15,'#c9b89c');}}
 return `<span class="world-illustration12" aria-hidden="true"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 260 115"><rect width="260" height="115" fill="#c5d0d3"/><path d="M32 67l97-48 98 49-96 48Z" fill="${k==='estate'?'#b4c3a2':'#b9c2c4'}"/>${content}</svg></span>`;}

function worldEstatePlanDialog12(id){const e=worldAsset12('estate',id),p=e.craft5;show(`<h2>${esc(e.name)} · pěstování a zpracování</h2><p class="sub">Záhony ukazují společný sklizňový cyklus plantáže. Změna odrůdy obnoví celý cyklus; nabídka předem ukáže investici a odpis.</p><div class="fields">${field('Odrůda porostu',`<select data-estate-variety="${e.id}">${ORIGIN_VARIETIES5[e.origin].map(k=>option(k,VARIETIES5[k].name,p.variety)).join('')}</select>`)}${field('Zpracování sklizně',`<select data-estate-process="${e.id}">${Object.entries(PROCESSES5).map(([k,x])=>option(k,x.name,p.process)).join('')}</select>`)}${field('Fermentace (hodiny)',`<input type="number" min="0" max="72" value="${p.hours}" data-estate-hours="${e.id}">`)}</div><button class="primary" id="worldEstatePreview12">Prověřit změnu</button>`);el('worldEstatePreview12').onclick=()=>estateCraftDialog5(id);}

function layoutDiagram9(floor,audit,route='guest'){
 const points=route==='guest'?audit.guest:audit.legs[Number(route)]?.path||[],stationColor={counter:'#535bbb',espresso:'#365b65',pickup:'#29765b'},cells=new Map(floor.items.flatMap(i=>stationCells5(i).map(([x,y])=>[x+','+y,i]))),hot=new Set(audit.narrow.map(p=>p.x+','+p.y));
 return `<svg class="layout-diagram9" viewBox="0 0 480 360" role="img" aria-label="Průchozí cesta mezi skutečnými stanicemi kavárny">${Array.from({length:48},(_,k)=>{const x=k%8,y=Math.floor(k/8),item=cells.get(x+','+y);return `<rect x="${x*60+2}" y="${y*60+2}" width="56" height="56" rx="5" fill="${item?stationColor[item.kind]||'#bdc6cd':hot.has(x+','+y)?'#f6dca1':'#edf2f6'}"/>${item&&x===item.x&&y===item.y?`<text x="${x*60+30}" y="${y*60+34}" text-anchor="middle" font-size="18" fill="${stationColor[item.kind]?'white':'#304454'}">${floor.items.indexOf(item)+1}</text>`:''}`;}).join('')}<polyline points="${points.map(p=>(p.x*60+30)+','+(p.y*60+30)).join(' ')}" fill="none" stroke="#da7445" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/>${points.map((p,i)=>i===0||i===points.length-1?`<circle cx="${p.x*60+30}" cy="${p.y*60+30}" r="8" fill="#da7445"/>`:'').join('')}<text x="30" y="353" text-anchor="middle" font-size="16">Vchod</text><text x="450" y="353" text-anchor="middle" font-size="16">Východ</text></svg><div class="layout-legend9">${floor.items.map((i,k)=>`<span><strong>${k+1}</strong> ${esc(STATIONS5[i.kind].name)}</span>`).join('')}</div>`;
}
function layoutDialog9(floor,seats=100,before=null){
 const frozen=cloneStudio5(floor),audit=floorRoutes9(frozen,seats),previous=before?floorRoutes9(before.floor,before.seats):null;
 show(`<h2>Jak funguje dispozice</h2><p>Trasy vedou volnými políčky. Průchodnost ${round(audit.flow*100)} % už ovlivňuje skutečnou kapacitu obsluhy.</p><div class="fields layout-fields9">${field('Zobrazit trasu',`<select id="layoutRoute9">${option('guest','Host: vchod → objednávka → výdej → východ','guest')}${audit.legs.map((l,i)=>option(i,STATIONS5[l.from].name+' → '+STATIONS5[l.to].name+' · '+l.steps+' kroků','guest')).join('')}</select>`)}</div><div id="layoutDiagram9">${layoutDiagram9(frozen,audit)}</div><div class="layout-summary9"><span>Místa: <strong>${audit.seats}</strong></span><span>Pracovní trasy: <strong>${audit.work} kroků</strong></span><span>Vchod k objednávce: <strong>${audit.entryWalk} kroků</strong></span></div>${frozen.items.some(i=>i.kind==='display')?'<p>Vitrína započítává čtvrtinu své trasy od objednávek do pracovního pohybu.</p>':''}${previous?`<p>Současná kavárna: ${previous.seats} míst, ${round(previous.flow*100)} % průchodnost. Návrh: ${audit.seats} míst, ${round(audit.flow*100)} %.</p>`:''}<p>${audit.narrow.length?'Zvýrazněná úzká místa sdílí alespoň tři trasy. Zkus přemístit stanici nebo nahradit velký stůl menším.':'Vybrané trasy se nesbíhají v úzkém společném místě.'} Rozbor úzkých míst pomůže porovnat varianty rozmístění.</p>`);
 el('layoutRoute9').onchange=()=>el('layoutDiagram9').innerHTML=layoutDiagram9(frozen,audit,el('layoutRoute9').value);
}
const LAYOUT_EDITOR9=gameEditorPanel6;
gameEditorPanel6=function(s){LAYOUT_EDITOR9(s);const b=document.createElement('button');b.id='layoutDraft9';b.textContent='Trasy a kapacita návrhu';el('gameContext6').querySelector('.game-panel-actions6').prepend(b);try{floorRoutes9(gameDraft6.design.floor,100);}catch{b.disabled=true;}b.onclick=()=>layoutDialog9(gameDraft6.design.floor,100,s);};
const LAYOUT_INTERIOR9=interiorView,LAYOUT_BIND9=bind;
interiorView=function(){const html=LAYOUT_INTERIOR9();return html+'<section class="card"><h2>Trasy a kapacita návrhu</h2><p>Porovnej přístup k objednávkám, výdeji a stolům před zaplacením přestavby.</p><button class="soft" id="layoutStudio9">Prohlédnout trasy</button></section>';};
bind=function(){LAYOUT_BIND9();if(el('layoutStudio9'))el('layoutStudio9').onclick=()=>{try{layoutDialog9(studioDraft5.design.floor,100,state.stores.find(s=>s.id===studioTarget5));}catch(e){toast(e.message);}};};
function gameLossText9(frame){return frame?`Odchody v tomto intervalu: fronta ${frame.lostQueue}, plná místa ${frame.lostSeats}, chybějící káva ${frame.lostStock}, zavření ${frame.lostClosing}. Požadavky na jídlo bez dodání: ${frame.foodMissing9||0}.`:'';}
const LAYOUT_OPERATION9=gameOperation6,LAYOUT_SLOT9=gameUpdateSlot6;
gameOperation6=function(){LAYOUT_OPERATION9();if(el('gameOperation6').hidden)return;const frame=worldCafeSnapshot6(gameSelection6.id,gameDay6,gameSlot6).slot;if(!frame)return;const p=document.createElement('p');p.id='gameReplayLoss9';p.textContent=gameLossText9(frame);el('gameOperation6').append(p);const b=document.createElement('button');b.id='gameReplayGuests9';b.textContent='Hosté a důvody odchodů';el('gameOperation6').append(b);b.onclick=()=>gameGuestsDialog9(gameSelection6.id,gameDay6,gameSlot6);};
gameUpdateSlot6=function(){LAYOUT_SLOT9();if(el('gameReplayLoss9'))el('gameReplayLoss9').textContent=gameLossText9(worldCafeSnapshot6(gameSelection6.id,gameDay6,gameSlot6).slot);};
function guestDialog9(data){show(`<h2>${esc(data.title)}</h2><p>${esc(data.reason)}</p><p>V tomto desetiminutovém intervalu: ${number(data.total)} ${esc(data.unit||'hostů')}. Postava představuje skupinu ze zaznamenaného provozu.</p>`);}

function gameGuestsDialog9(id,day,slot){const snap=worldCafeSnapshot6(id,day,slot),p=snap.slot;if(!p)return;show(`<h2>${esc(loc(id).name)} · hosté v ${Math.floor(p.hour)}:${String(Math.round(p.hour%1*60)).padStart(2,'0')}</h2><p>Zaznamenaný T${snap.week}, ${DAYS5[day]}. Počty patří tomuto desetiminutovému intervalu.</p>${rows([['Příchozí',p.arrivals],['Obslouženo',p.served],['Zůstává ve frontě',p.queue],['Obsazená místa',p.occupied],['Odchody: čekání přes trpělivost',p.lostQueue],['Odchody: plná místa',p.lostSeats],['Odchody: chybějící káva',p.lostStock],['Odchody: objednávka do zavření',p.lostClosing],['Požadavky na jídlo bez dodání',p.foodMissing9||0]])}<p>Jídlo ukazuje požadavky rozdělené z denního výsledku podle obsloužených návštěv. Jeden host může chtít více kusů a může již mít zaplacenou kávu.</p>`);}
